import json, re
from pathlib import Path

p = Path('Answers/annotation/completion_round4_ls_input.json')
rows = json.loads(p.read_text(encoding='utf-8'))

required = [
    'text','level','answer','claims','corpus','doc_id','source','dataset','category','question',
    '_warnings','meta_html','reasoning','record_id','text_html','claims_html','level_label',
    'unanswerable','_generation_seconds','expected_location_hint'
]

missing = []
invalid_sid = []
claims_dash = []

def text_ids(text):
    return set(re.findall(r'(?<!\d)(\d+)(?=\s)', text))

for i,r in enumerate(rows, start=1):
    miss = [k for k in required if k not in r]
    if miss:
        missing.append((i, r.get('record_id'), miss))
    tids = text_ids(r.get('text',''))
    for c in r.get('claims', []):
        for sid in c.get('sentence_ids', []):
            if str(sid) not in tids:
                invalid_sid.append((r.get('record_id'), sid))
    if r.get('claims') and 'משפטים: —' in (r.get('claims_html') or ''):
        claims_dash.append(r.get('record_id'))

print('records', len(rows))
print('missing_key_records', len(missing))
print('invalid_sentence_ids', len(invalid_sid))
print('claims_html_dash_with_claims', len(claims_dash))

if missing:
    print('missing_examples', missing[:3])
if invalid_sid:
    print('invalid_sid_examples', invalid_sid[:5])
if claims_dash:
    print('claims_dash_examples', claims_dash[:5])
